import{_ as e,o,c as d,ag as i}from"./chunks/framework.DaCm-iTo.js";const h=JSON.parse('{"title":"Introduction","description":"","frontmatter":{},"headers":[],"relativePath":"en/guide/introduction.md","filePath":"en/guide/introduction.md","lastUpdated":null}'),r={name:"en/guide/introduction.md"};function a(s,t,n,l,c,u){return o(),d("div",null,[...t[0]||(t[0]=[i('<h1 id="introduction" tabindex="-1">Introduction <a class="header-anchor" href="#introduction" aria-label="Permalink to &quot;Introduction&quot;">​</a></h1><p>Emaki Series is a set of RPG plugin modules for Minecraft 1.21.8+. CoreLib holds shared infrastructure; business modules add attributes, equipment, strengthening, gems, levels, skills, cooking stations, and the advancement codex.</p><h2 id="technical-baseline" tabindex="-1">Technical baseline <a class="header-anchor" href="#technical-baseline" aria-label="Permalink to &quot;Technical baseline&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Item</th><th>Value</th></tr></thead><tbody><tr><td>Server</td><td>Paper 1.21.8+ (minimum supported: 1.21.8)</td></tr><tr><td>API</td><td><code>paper-api:1.21.8-R0.1-SNAPSHOT</code></td></tr><tr><td>Java</td><td><code>25</code></td></tr><tr><td>paper-plugin.yml api-version</td><td><code>1.21.8</code></td></tr><tr><td>Build system</td><td>Maven multi-module project</td></tr></tbody></table><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to &quot;Modules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Module</th><th>Version</th><th>Aggregation</th><th>Purpose</th></tr></thead><tbody><tr><td>EmakiCoreLib</td><td><code>4.6.0</code></td><td>default</td><td>Shared infrastructure for all business modules.</td></tr><tr><td>EmakiAttribute</td><td><code>4.6.0</code></td><td>default</td><td>Attributes, resources, damage, conditions, and API bridges.</td></tr><tr><td>EmakiForge</td><td><code>4.6.0</code></td><td>default</td><td>Forging, blueprint requirements, material contributions, quality, recipe book.</td></tr><tr><td>EmakiStrengthen</td><td><code>4.6.0</code></td><td>default</td><td>Star strengthening, protection, failure handling, presentation.</td></tr><tr><td>EmakiCooking</td><td><code>4.1.0</code></td><td>default</td><td>World-based cooking stations.</td></tr><tr><td>EmakiLevel</td><td><code>1.4.0</code></td><td>default</td><td>Multiple level types, exp sources, requirements, PDC, placeholders, and MythicMobs exp drops.</td></tr><tr><td>EmakiCodex</td><td><code>1.0.0</code></td><td>default</td><td>Vanilla advancement codex pages, advancement config, and CoreLib action triggers.</td></tr><tr><td>EmakiGem</td><td><code>2.6.0</code></td><td>private-modules</td><td>Gems, sockets, opening, inlay, extraction, upgrades.</td></tr><tr><td>EmakiSkills</td><td><code>2.6.0</code></td><td>private-modules</td><td>Active/passive skills, triggers, resources, MythicMobs bridge.</td></tr><tr><td>EmakiItem</td><td><code>2.6.0</code></td><td>private-modules</td><td>Custom items, sets, triggers, auto update.</td></tr><tr><td>EmakiStorage</td><td><code>1.0.0</code></td><td>private-modules</td><td>Paged GUI warehouse, large per-slot quantities, capacity tiers, paid unlocks.</td></tr></tbody></table><blockquote><p><code>private-modules</code> is a profile declared in the root <code>pom.xml</code>. It activates automatically when a <code>.key</code> file exists in the project root and adds EmakiSkills, EmakiGem, EmakiItem, and EmakiStorage to the build.</p></blockquote><p>Besides the server plugins above, the project also builds the per-module <code>emaki-*-api</code> compile-time-only jars. None of them are server plugins, so do not put them into <code>plugins/</code>. The <code>emaki.jiuwu.craft.skills.api.pdc</code> package in <code>emaki-skills-api</code> owns the equipment skill PDC codec contract and is shaded and relocated into Item, Forge, Gem, and Strengthen at build time.</p><h2 id="why-corelib-exists" tabindex="-1">Why CoreLib exists <a class="header-anchor" href="#why-corelib-exists" aria-label="Permalink to &quot;Why CoreLib exists&quot;">​</a></h2><p>Most modules need the same infrastructure: actions, GUI sessions, item-source resolution, PDC storage, economy access, expressions, and structured item presentation. CoreLib centralizes those pieces so business modules can focus on their own gameplay rules.</p><h2 id="common-module-combinations" tabindex="-1">Common module combinations <a class="header-anchor" href="#common-module-combinations" aria-label="Permalink to &quot;Common module combinations&quot;">​</a></h2><ul><li><strong>Attribute-only combat</strong>: install CoreLib + Attribute. Add PlaceholderAPI, MythicMobs, or MMOItems only if you use those integrations.</li><li><strong>Equipment progression</strong>: install CoreLib + Attribute + Item + Forge + Strengthen + Gem.</li><li><strong>Level progression</strong>: install CoreLib + Level. Add PlaceholderAPI, MythicMobs, Attribute, Cooking, or Forge when progression needs placeholders, mob drops, attributes, or process rewards.</li><li><strong>Skill system</strong>: install CoreLib + Skills + MythicMobs. Add Attribute, Item, or Level when skills need resources, attributes, equipment unlocks, or level requirements.</li><li><strong>Life-skill gameplay</strong>: install CoreLib + Cooking. Add Level for cooking/profession exp, and add CraftEngine, ItemsAdder, or Nexo when stations use custom blocks or items.</li><li><strong>Advancement codex</strong>: install CoreLib + Codex. Add PacketEvents for advancement tree coordinate injection, and PlaceholderAPI or MythicMobs for their integrations.</li></ul>',12)])])}const p=e(r,[["render",a]]);export{h as __pageData,p as default};
